//! A restricted simplification follows C's AllowSimplify flags: a CmpMap
//! with RestrictedSimplify set nominates only components that have
//! AllowSimplify set, and a merge gives the Mappings it creates the flag
//! when every Mapping it consumed had it (mapping.c `astMapMerge_`), so a
//! chain of allowed merges continues.
//!
//! `allow_simplify_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/allow_simplify_probe.c`.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "allow_simplify_oracle/cases.rs"]
mod cases;

use ast_core::mappings::Mapping;
use ast_core::{AnyObject, from_native_string, to_native_string};

fn text(lines: &[&str]) -> String {
    let mut s = lines.join("\n");
    s.push('\n');
    s
}

#[test]
fn restricted_simplification_follows_the_c_library() {
    let mut failures = Vec::new();
    for &(name, input, want) in cases::CASES {
        let obj = from_native_string(&text(input)).unwrap();
        let map = obj.as_mapping().expect("a Mapping");
        let simplified = <dyn Mapping>::simplify(map).unwrap();
        let out = AnyObject::from_mapping(simplified.as_ref()).expect("a known class");
        let got = to_native_string(&out).unwrap();
        if got != text(want) {
            failures.push(format!("{name}:\n{got}\nC gives:\n{}", text(want)));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
